package com.hsm.account.controller;
import com.hsm.account.dto.ProfileDtos;import com.hsm.account.entity.User;import com.hsm.account.service.AccountService;import com.hsm.common.ApiException;import com.hsm.security.SessionFilter;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profile") public class ProfileController {private final AccountService service;public ProfileController(AccountService s){service=s;} private User user(org.springframework.web.context.request.NativeWebRequest r){return (User)r.getAttribute(SessionFilter.USER,2);} @GetMapping("/{id}") ProfileDtos.ProfileResponse get(@PathVariable Long id){return service.profile(id);} @GetMapping("/me") ProfileDtos.ProfileResponse me(org.springframework.web.context.request.NativeWebRequest r){User u=user(r);if(u==null)throw new ApiException(401,"UNAUTHENTICATED","Authentication is required.");return service.profile(u.getId());} @PutMapping("/me") ProfileDtos.ProfileResponse update(@Valid @RequestBody ProfileDtos.UpdateProfileRequest x,org.springframework.web.context.request.NativeWebRequest r){User u=user(r);if(u==null)throw new ApiException(401,"UNAUTHENTICATED","Authentication is required.");return service.update(u.getId(),x);} }
